target.css:
:root {
  --ink: #26352a;
  --paper: #fffdf7;
  --line: #cdd8c8;
  --moss: #3f7048;
  --leaf: #e3f0da;
}

.compost-pass {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 430px;
  padding: 14px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.pass-icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  background: var(--leaf);
  border-radius: 50%;
  font-size: 27px;
}

.pass-content h1 {
  margin: 2px 0;
  color: var(--ink);
  font-size: 20px;
}

.eyebrow,
.details {
  margin: 0;
  color: var(--moss);
  font-size: 12px;
}

.eyebrow {
  font-weight: 700;
  letter-spacing: 0.08em;
}
